//! File-type icons from Material Design Icons (Pictogrammers, https://pictogrammers.com/library/mdi/,
//! Apache License 2.0): one glyph per kind of file, each in its own colour from an expanded
//! palette, nudged a little toward the desktop's accent so they sit in the theme.
//!
//! Only the shapes are kept here (24×24 path data); the colour is put in when drawn.

use eframe::egui::Color32;

use crate::palette::mix;

/// One kind of file: its glyph and its own colour.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Kind {
    pub key: &'static str,
    pub path: &'static str,
    pub color: Color32,
}

const fn rgb(hex: u32) -> Color32 {
    Color32::from_rgb((hex >> 16) as u8, (hex >> 8) as u8, hex as u8)
}

