fn k(key: &'static str, path: &'static str, color: Color32) -> Kind {
    Kind { key, path, color }
}

/// A file's kind, by its name (special names first, then the extension).
pub fn for_file(name: &str) -> Kind {
    use colors as c;
    let lower = name.to_lowercase();
    let stem = lower.split('.').next().unwrap_or("");
    match lower.as_str() {
        "package.json" => return k("npm", NPM, c::NPM),
        "dockerfile" | "containerfile" | ".dockerignore" | "docker-compose.yml" | "docker-compose.yaml" | "compose.yml" | "compose.yaml" => return k("docker", DOCKER, c::DOCKER),
        ".gitignore" | ".gitattributes" | ".gitmodules" | ".gitkeep" => return k("git", GIT, c::GIT),
        "makefile" | "gnumakefile" | "cmakelists.txt" | "justfile" | "meson.build" | "build.rs" | "build.gradle" | "pkgbuild" => return k("build", HAMMER_WRENCH, c::BUILD),
        "cargo.toml" | "pyproject.toml" => return k("config", COG_OUTLINE, c::CONFIG),
        _ => {}
    }
    if lower.ends_with(".lock") || lower.ends_with("-lock.json") || lower == "yarn.lock" || lower.ends_with(".lockb") {
        return k("lock", LOCK, c::LOCK);
    }
    if matches!(stem, "license" | "licence" | "copying" | "notice") {
        return k("license", LICENSE, c::LICENSE);
    }
    if stem == "readme" {
        return k("readme", INFORMATION_OUTLINE, c::README);
    }
    if lower == ".env" || lower.starts_with(".env.") || lower.ends_with(".pem") || lower.ends_with(".key") {
        return k("secret", KEY_VARIANT, c::SECRET);
    }
    let ext = lower.rsplit_once('.').map(|(_, e)| e).unwrap_or("");
    match ext {
        "rs" => k("rust", LANGUAGE_RUST, c::RUST),
        "py" | "pyi" | "pyw" | "ipynb" => k("python", LANGUAGE_PYTHON, c::PYTHON),
        "js" | "mjs" | "cjs" => k("javascript", LANGUAGE_JAVASCRIPT, c::JAVASCRIPT),
        "ts" | "mts" | "cts" => k("typescript", LANGUAGE_TYPESCRIPT, c::TYPESCRIPT),
        "jsx" | "tsx" => k("react", REACT, c::REACT),
        "json" | "jsonc" | "json5" | "geojson" => k("json", CODE_JSON, c::JSON),
        "html" | "htm" | "xhtml" => k("html", LANGUAGE_HTML5, c::HTML),
        "css" => k("css", LANGUAGE_CSS3, c::CSS),
        "scss" | "sass" | "less" => k("sass", SASS, c::SASS),
        "go" | "mod" | "sum" => k("go", LANGUAGE_GO, c::GO),
        "c" | "h" => k("c", LANGUAGE_C, c::C),
        "cpp" | "cc" | "cxx" | "hpp" | "hh" | "hxx" => k("cpp", LANGUAGE_CPP, c::CPP),
        "java" | "jar" | "class" => k("java", LANGUAGE_JAVA, c::JAVA),
        "kt" | "kts" => k("kotlin", LANGUAGE_KOTLIN, c::KOTLIN),
        "rb" | "gemspec" => k("ruby", LANGUAGE_RUBY, c::RUBY),
        "php" => k("php", LANGUAGE_PHP, c::PHP),
        "lua" => k("lua", LANGUAGE_LUA, c::LUA),
        "swift" => k("swift", LANGUAGE_SWIFT, c::SWIFT),
        "cs" => k("csharp", LANGUAGE_CSHARP, c::CSHARP),
        "md" | "markdown" | "mdx" => k("markdown", LANGUAGE_MARKDOWN, c::MARKDOWN),
        "sh" | "bash" | "zsh" | "fish" | "ksh" | "ps1" | "bat" | "cmd" => k("shell", CONSOLE, c::SHELL),
        "toml" | "ini" | "cfg" | "conf" | "properties" | "editorconfig" => k("config", COG_OUTLINE, c::CONFIG),
        "yaml" | "yml" => k("yaml", FILE_COG_OUTLINE, c::YAML),
        "xml" | "plist" | "xsd" | "xsl" => k("xml", XML, c::XML),
        "sql" | "db" | "sqlite" | "sqlite3" => k("database", DATABASE, c::DATABASE),
        "png" | "jpg" | "jpeg" | "gif" | "webp" | "bmp" | "ico" | "svg" | "avif" | "heic" | "tif" | "tiff" | "psd" | "xcf" => k("image", FILE_IMAGE, c::IMAGE),
        "mp3" | "ogg" | "oga" | "wav" | "flac" | "m4a" | "opus" | "aac" => k("audio", FILE_MUSIC, c::AUDIO),
        "mp4" | "mkv" | "webm" | "mov" | "avi" | "m4v" => k("video", FILE_VIDEO, c::VIDEO),
        "pdf" => k("pdf", FILE_PDF_BOX, c::PDF),
        "zip" | "tar" | "gz" | "tgz" | "xz" | "bz2" | "zst" | "7z" | "rar" | "deb" | "rpm" | "flatpak" => k("archive", ZIP_BOX, c::ARCHIVE),
        "ttf" | "otf" | "woff" | "woff2" => k("font", FORMAT_FONT, c::FONT),
        "txt" | "log" | "rst" | "adoc" | "org" => k("text", TEXT_BOX_OUTLINE, c::TEXT),
        "csv" | "tsv" | "ods" | "xlsx" | "xls" => k("sheet", FILE_TABLE, c::SHEET),
        "nix" => k("nix", NIX, c::NIX),
        "vue" => k("vue", VUEJS, c::VUE),
        "lockb" => k("lock", LOCK, c::LOCK),
        _ => k("file", FILE_OUTLINE, c::OTHER),
    }
}

/// A folder's kind, by its name; `accent` is the folders' colour.
pub fn for_folder(name: &str, open: bool, accent: Color32) -> Kind {
    let lower = name.to_lowercase();
    let path = match lower.as_str() {
        ".git" | ".github" | ".gitlab" | ".config" | ".vscode" | ".idea" | ".cargo" | "config" | "settings" => FOLDER_COG,
        "images" | "img" | "assets" | "icons" | "pictures" | "media" | "screenshots" | "shots" => FOLDER_IMAGE,
        "docs" | "doc" | "documentation" | "notes" => FOLDER_TEXT,
        _ if open => FOLDER_OPEN,
        _ => FOLDER,
    };
    Kind { key: "folder", path, color: accent }
}

/// A kind's colour in the theme: its own, moved a little toward the accent, and a touch darker
/// on light backgrounds (so yellows still read) or lighter on dark ones.
pub fn tint(base: Color32, accent: Color32, dark: bool) -> Color32 {
    let c = mix(base, accent, 0.14);
    if dark { mix(c, Color32::WHITE, 0.06) } else { mix(c, Color32::BLACK, 0.12) }
}

/// The icon as an SVG, ready to draw.
pub fn svg(path: &str, color: Color32) -> String {
    format!(r##"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="{path}" fill="#{:02x}{:02x}{:02x}"/></svg>"##, color.r(), color.g(), color.b())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn kinds_by_name() {
        assert_eq!(for_file("main.rs").key, "rust");
        assert_eq!(for_file("Cargo.lock").key, "lock");
        assert_eq!(for_file("README.md").key, "readme");
        assert_eq!(for_file("Dockerfile").key, "docker");
        assert_eq!(for_file("app.TSX").key, "react");
        assert_eq!(for_file("release").key, "file");
        assert_eq!(for_folder(".github", false, Color32::RED).path, FOLDER_COG);
        assert_eq!(for_folder("src", true, Color32::RED).path, FOLDER_OPEN);
        // Nudged, not replaced.
        let t = tint(colors::PYTHON, Color32::from_rgb(0xe6, 0x61, 0x00), true);
        assert!(t.b() > t.r());
        assert!(crate::icons::render_svg(svg(LANGUAGE_RUST, t).as_bytes(), 32).is_some());
    }
}

